// Generated by `npm run gen`.
// Do not edit by hand: Rust owns the .loom schema and the block
// catalogue, and this file is how TypeScript learns them.
// This file has been generated by Specta. Do not edit this file manually.
export type Acknowledged = {
	ok: boolean,
	count: number,
};

/**  What survives from one event to the next in a live graph. */
export type Between = {
	keepState: boolean,
	restartOnCrash: boolean,
};

/**  One block on the canvas. */
export type Block = {
	id: string,
	/**  A key into the built-in catalogue, or `custom`. */
	kind: string,
	/**  Overrides the kind's own title when the user renames the block. */
	title?: string | null,
	position: Position,
	size?: Size | null,
	view: View,
	/**  Validated against the kind's setting definitions. */
	settings: { [key in string]: Setting },
	/**  A custom block's parsed interface: the ports its signature produced. */
	ports: Port[],
	source?: Source | null,
	disabled?: boolean,
	breakpoint?: boolean,
	/**  The loop frame that contains this block, if any. */
	frame?: string | null,
};

/**  One entry in the catalogue. */
export type BlockKind = {
	/**  The key a `.loom` file writes. */
	id: string,
	title: string,
	category: Category,
	/**  A name in the shared icon set. */
	icon: string,
	ports: PortDef[],
	settings: SettingDef[],
	/**
	 *  A source emits on its own initiative and keeps the graph armed, so a
	 *  graph that holds one never finishes (SPEC §8.2).
	 */
	source: boolean,
	/**
	 *  Whether this kind can be drawn in Stage view, which is to say whether it
	 *  has a picture (SPEC §3.4).
	 */
	stage: boolean,
	/**  One line, shown in the library and the inspector. */
	summary: string,
};

/**
 *  The state a block is in, which is what the canvas draws as its status dot
 *  (SPEC §3.2).
 */
export type BlockState = 
/**  Placed, never run. */
"idle" | 
/**  Waiting on an upstream block. */
"queued" | 
/**  Executing now; its wires animate. */
"running" | 
/**  Produced a value this run. */
"done" | 
/**  Threw. The console holds the trace. */
"error" | 
/**  Skipped, wires kept. */
"disabled" | 
/**
 *  A capability rather than a step: it was bound to a holder and will run
 *  only if called.
 * 
 *  Not one of §3.2's seven, because §3.2 describes blocks that execute.
 *  A Terminal offered to a model through a Toolbox never "runs" on its own
 *  — it waits to be called — and showing it as *done* would claim it had
 *  produced a value when it had not been asked for one.
 */
"ready";

/**
 *  The ten shelves of the library. A category carries its own colour, shared
 *  between the library shelf and the block header (SPEC §6).
 */
export type Category = "models" | "capabilities" | "runtimes" | "senses" | "memory" | "actuators" | "data" | "control" | "human" | "custom";

export type Control = "text" | "multiline" | "number" | "range" | "bool" | "select" | "path";

/**
 *  The only two answers. There is no "refuse": the application may warn before
 *  a dangerous action and may not prevent one, so the choice is between going
 *  ahead and stopping the whole run — never between going ahead and being
 *  overruled on this one step (SPEC §12.1).
 */
export type Decision = "continue" | 
/**  Continue, and do not ask again for this block during this run. */
"continueAlways" | "stop";

export type Defaults = {
	provider: string,
	model: string,
};

/**
 *  One end of a wire. It names a *node*, which is a block or a loop frame:
 *  a frame has ports of its own (`items` in, `item`, `results`, `done` and
 *  `errors` out), so wires land on frames as well as on blocks (SPEC §8.4).
 */
export type Endpoint = {
	node: string,
	port: string,
};

export type EngineStatus = {
	version: string,
	/**  The workspace folder this engine is serving. */
	workspace: string,
	/**  How many graphs it can see. */
	graphs: number,
	/**
	 *  The catalogue's size, so a shell can tell at a glance whether it is
	 *  talking to an engine that knows the same blocks it does.
	 */
	kinds: number,
};

export type Execution = {
	runtime: string,
	concurrency: number,
	timeoutSec: number,
};

/**
 *  A loop: a dashed frame on the canvas, not a card. Blocks inside it repeat
 *  once per item (SPEC §8.4).
 */
export type Frame = {
	id: string,
	kind: FrameKind,
	position: Position,
	size: Size,
	/**  The port the frame iterates. */
	over: Endpoint,
	/**  The name each item takes inside the frame. */
	as: string,
	parallel: number,
	max: number,
	stopWhen?: Endpoint | null,
	continueOnError: boolean,
};

export type FrameKind = "loop";

/**  A setting the code asked for, with the control it should draw. */
export type Generated = {
	name: string,
	/**  Title-cased from the name: `max_items` becomes `Max items`. */
	label: string,
	kind: Control,
	/**
	 *  The default, exactly as it was written in the code. Editing the setting
	 *  rewrites this text in place (§10.3), so it is kept verbatim rather than
	 *  parsed and re-printed: `0.60` should not silently become `0.6`.
	 */
	default: string,
	min: number,
	max: number,
	/**  A `Literal[...]` or a union of strings becomes a choice. */
	options: string[],
};

/**  One `.loom` file. */
export type Graph = {
	version: number,
	id: string,
	name: string,
	description?: string | null,
	runMode: RunMode,
	/**
	 *  On by default. Turning it off allows remote model providers; the first
	 *  send of a run to any remote service warns (SPEC §15.4).
	 */
	localOnly: boolean,
	execution: Execution,
	defaults: Defaults,
	overlap: Overlap,
	between: Between,
	/**
	 *  Secret *names*, never values: values live in the OS keyring, so a graph
	 *  is safe to commit (SPEC §12.4). Sorted, like every other map in the
	 *  format: their order carries no meaning, and sorting is what lets two
	 *  hands produce one file.
	 */
	env: { [key in string]: string },
	blocks: Block[],
	frames: Frame[],
	wires: Wire[],
	ui: Ui,
};

/**  One row of the workspace list. Enough to draw a tab without opening the file. */
export type GraphSummary = {
	/**  Relative to the workspace root, so it is the same on any machine. */
	path: string,
	id: string,
	name: string,
	blocks: number,
	wires: number,
	runMode: RunMode,
};

/**  A block derived from one function. */
export type Interface = {
	/**  The function's own name, which becomes the block's title. */
	name: string,
	/**  The docstring, or the comment above the function. */
	description: string | null,
	/**
	 *  From `@block(icon=…)`. None leaves the block with the Custom shelf's
	 *  default rather than guessing one from the name.
	 */
	icon: string | null,
	/**  From `@block(category=…)`, which decides the shelf it lands on. */
	category: string | null,
	ports: Port[],
	settings: Generated[],
	/**
	 *  Where the function starts, 1-based. Used to point at the right line
	 *  when something is wrong with it.
	 */
	line: number,
};

/**  The languages a custom block may be written in (SPEC §15.8). */
export type Language = "python" | 
/**  The TypeScript kind runs plain JavaScript too. */
"typescript" | "javascript" | "shell";

/**  Where a console line came from, so the shell can colour it by category. */
export type Level = "info" | "warn" | "error";

/**
 *  Bytes that are too big to put in an event, named by where they landed.
 * 
 *  An image or an audio buffer goes to a file in the run's scratch folder and
 *  travels as a reference. The alternative is base64 in a JSON line, which
 *  would make the console log unreadable and the socket the bottleneck.
 */
export type Media = {
	path: string,
	/**  `image/png`, `audio/wav`. The shell picks a preview from it. */
	mime: string,
	bytes: number,
};

/**
 *  A graph, with everything the shell needs to draw it and nothing it would
 *  have to ask for straight afterwards.
 */
export type OpenGraph = {
	path: string,
	graph: Graph,
	/**
	 *  What is wrong with it, if anything. A graph with problems still opens
	 *  and still draws; the shell shows these rather than refusing the file.
	 */
	problems: string[],
};

/**  What happens when an event arrives while the previous one is still running. */
export type Overlap = {
	policy: OverlapPolicy,
	maxQueue: number,
	coalesceMs: number,
	loopParallel: number,
};

/**  What happens when an event arrives while the previous one is still running. */
export type OverlapPolicy = "queue" | "dropNewest" | "dropOldest" | "coalesce";

/**  A port declared by a custom block, derived from its signature (SPEC §10.2). */
export type Port = {
	name: string,
	type: PortType,
	side: Side,
	optional?: boolean,
};

/**  One port a kind declares. */
export type PortDef = {
	name: string,
	type: PortType,
	side: Side,
	/**
	 *  An optional port is hidden until it is wired or the block is selected
	 *  (SPEC §4.5).
	 */
	optional: boolean,
	/**
	 *  A dynamic port grows a new empty slot as each one is filled: the
	 *  Toolbox's `tools` and the Memory hub's `memory` (SPEC §9).
	 */
	dynamic: boolean,
};

/**
 *  The ten port types. A wire is coloured by its type, and the type is what
 *  makes a connection legal or refuses it mid-drag. There is no untyped wire.
 */
export type PortType = 
/**  Prompts, stdout, any string. */
"text" | 
/**  One callable, or a bundle of them. A handle, not a flow. */
"tools" | 
/**  A store the model reads and writes. A handle, not a flow. */
"memory" | 
/**  Structured json or a record. */
"data" | 
/**  Output arriving incrementally. */
"stream" | 
/**  Frames from a camera or a file. */
"image" | 
/**  Samples from a microphone. */
"audio" | 
/**  A path or blob on disk. */
"file" | 
/**  A trigger or control flow, never a value. */
"exec" | 
/**  Accepts every value type. */
"any";

/**  A value on a named port. */
export type PortValue = {
	port: string,
	value: Value,
};

export type Position = {
	x: number,
	y: number,
};

export type Reparsed = {
	/**  Every function the file declares, in the order it declares them. */
	blocks: Interface[],
	/**  The one the request asked for, or the first. */
	chosen: Interface | null,
	error: SourceError | null,
};

/**
 *  Anything the engine sends back.
 * 
 *  Serialise only: the engine writes replies and the shell, which is
 *  TypeScript, reads them. Nothing in Rust parses one back, and the catalogue
 *  inside it is a table of `&'static str` that could not be parsed anyway.
 */
export type Reply = { result: "engineStatus"; data: EngineStatus } | { result: "catalogue"; data: BlockKind[] } | { result: "workspace"; data: GraphSummary[] } | { result: "graph"; data: OpenGraph } | { result: "saved"; data: Saved } | { result: "running"; data: RunStarted } | 
/**
 *  What the code says the block's interface is, or why it could not be
 *  read. A failure is a reply, not an error: the block shows the line
 *  number and keeps its previous interface (SPEC §10.4).
 */
{ result: "interface"; data: Reparsed } | 
/**  How many runs stopped, or whether a warning was answered. */
{ result: "acknowledged"; data: Acknowledged } | 
/**  Not an exception: the shell shows it and carries on (SPEC §12.1). */
{ result: "error"; data: RpcError };

/**  Anything the shell sends. */
export type Request = 
/**  What the engine is and what it can reach. */
{ method: "engine.status" } | 
/**
 *  Every built-in block kind. The shell has a generated copy for its own
 *  types, but the running engine is what decides what can actually be run.
 */
{ method: "graph.catalogue" } | 
/**  The graphs in the workspace, by relative path. */
{ method: "workspace.list" } | 
/**  Read one graph. */
{ method: "graph.open"; params: {
	path: string,
} } | 
/**
 *  Write one graph back, in canonical form.
 * 
 *  The shell sends the whole graph rather than a patch. It is a few
 *  kilobytes, it makes the write atomic from the shell's point of view,
 *  and it means the engine never has to reconstruct a document from a
 *  stream of edits it might have missed.
 */
{ method: "graph.save"; params: {
	path: string,
	graph: Graph,
} } | 
/**
 *  Run a graph. Answers immediately with the run's id; everything the run
 *  has to say arrives afterwards as events carrying that id.
 * 
 *  The graph comes from the shell rather than from disk, so what runs is
 *  what is on screen. Autosave means the two are almost always the same,
 *  but "almost always" is not a thing to build a Run button on: a person
 *  who edits and immediately runs should get the edit.
 */
{ method: "run.start"; params: {
	path: string,
	graph: Graph,
} } | 
/**  Stop a run, or every run on this connection when given none. */
{ method: "run.stop"; params: {
	run?: string | null,
} } | 
/**  Answer a warning the run is parked on (SPEC §12.1). */
{ method: "run.continue"; params: {
	warning: string,
	decision: Decision,
} } | 
/**
 *  Re-read a custom block's signature (SPEC §10.3).
 * 
 *  The code comes from the shell rather than from disk for the same reason
 *  `run.start` does: a block is re-parsed on every save and every editor
 *  blur, and what the person is looking at is what should be parsed.
 */
{ method: "block.reparse"; params: {
	language: Language,
	code: string,
	/**
	 *  Which function, when the file declares several (SPEC §10.5). None
	 *  takes the first.
	 */
	function?: string | null,
} };

export type RpcError = {
	/**  A stable key the shell can branch on. */
	code: string,
	/**  One sentence, already fit to show a person. */
	message: string,
};

export type RunEvent = { event: "run.started"; data: {
	run: string,
	graph: string,
	/**
	 *  Every block the plan will visit, in the order it will visit them.
	 *  The shell draws the whole run as queued before anything happens,
	 *  which is what makes progress legible rather than surprising.
	 */
	order: string[],
} } | { event: "block.state"; data: {
	run: string,
	block: string,
	state: BlockState,
} } | 
/**
 *  A chunk of output as it is produced: model tokens, a line of stdout.
 *  Sent as it happens, which is what makes streaming visible rather than a
 *  value that appears all at once (SPEC §5.3).
 */
{ event: "block.output"; data: {
	run: string,
	block: string,
	port: string,
	chunk: string,
} } | 
/**  A block finished and its output ports hold these values. */
{ event: "block.done"; data: {
	run: string,
	block: string,
	/**  One entry per output port that produced something. */
	outputs: PortValue[],
	ms: number,
	/**
	 *  The short line the block shows inline while the run is in flight:
	 *  `exit 101`, `1.2k tokens · 41/s` (SPEC §3.2).
	 */
	figure: string | null,
} } | { event: "block.error"; data: {
	run: string,
	block: string,
	message: string,
	/**  The full trace, for the console. The message is the one line. */
	detail: string | null,
} } | 
/**  A wire carried a value. The canvas animates it (SPEC §5.3). */
{ event: "wire.active"; data: {
	run: string,
	wire: string,
} } | { event: "console"; data: {
	run: string,
	/**  The block it came from, or none for the run itself. */
	source: string | null,
	level: Level,
	message: string,
} } | 
/**
 *  A tool call, which is the trace tab's unit: who called what, with what,
 *  and what came back.
 */
{ event: "tool.call"; data: {
	run: string,
	/**  The block holding the handle — the model that made the call. */
	caller: string,
	/**  The block that answers it. */
	callee: string,
	name: string,
	/**
	 *  Whatever the model sent. `unknown` on the TypeScript side, for the
	 *  same reason as `run::Value::Data`.
	 */
	arguments: unknown,
} } | { event: "tool.result"; data: {
	run: string,
	caller: string,
	callee: string,
	name: string,
	result: string,
	ok: boolean,
	ms: number,
} } | 
/**
 *  The run has stopped and is waiting for a person.
 * 
 *  This is SPEC §12.1 made concrete: the engine describes the action and
 *  waits. It does not decide, and there is no variant here for refusing —
 *  the only replies are continue and stop, because the application may warn
 *  before a dangerous action and may not prevent one.
 */
{ event: "run.warning"; data: {
	run: string,
	/**  Answered with `run.continue`. */
	id: string,
	block: string,
	/**  What is about to happen, in words, already fit to show. */
	action: string,
	/**  Why it warranted a warning (SPEC §12.2). */
	reason: string,
	/**  Whether the prompt offers "don't warn again for this block". */
	remember: boolean,
} } | 
/**
 *  Tokens in and out, and what they cost. Local models are free, and the
 *  panel says so rather than showing a zero (SPEC §8.5).
 */
{ event: "run.usage"; data: {
	run: string,
	block: string,
	tokensIn: number,
	tokensOut: number,
	/**  Tokens per second, over the whole response. */
	rate: number,
	local: boolean,
} } | { event: "run.finished"; data: {
	run: string,
	outcome: RunOutcome,
	ms: number,
	/**
	 *  Named outputs, in the order their blocks appear in the file. What a
	 *  headless run would print.
	 */
	results: PortValue[],
} };

/**
 *  How a graph runs. Paused is a run state, not a graph setting, so it is not
 *  here (SPEC §8).
 */
export type RunMode = "once" | "live" | "schedule";

/**  How a run ended. */
export type RunOutcome = "finished" | 
/**  The user pressed stop. */
"stopped" | 
/**
 *  At least one block errored. The run still reached the end: a block that
 *  throws does not tear the graph down, it reports (SPEC §12.1).
 */
"failed";

export type RunStarted = {
	run: string,
	/**  What the plan could not do. The run starts anyway (SPEC §12.1). */
	problems: string[],
};

/**  What a save produced. */
export type Saved = {
	path: string,
	/**
	 *  The canonical form the engine wrote. Positions come back snapped to the
	 *  grid, so the shell can adopt what is actually on disk rather than
	 *  holding a document that differs from the file by a rounding.
	 */
	graph: Graph,
	problems: string[],
	/**
	 *  False when the file already held these exact bytes. The shell uses it to
	 *  avoid saying "saved" when nothing changed.
	 */
	written: boolean,
};

/**
 *  A setting value. Deliberately small: a setting is a scalar, a list or a
 *  record, and nothing in the format needs more than that.
 * 
 *  `Int` is 32-bit rather than 64. A setting holds a port number, a count, a
 *  timeout — never something that needs more — and JSON, which is what carries
 *  these over the socket, has one number type anyway. A whole number too large
 *  for `Int` is read as a `Float`, which is the same precision JSON would have
 *  given it; because the writer prints an integral float without its point, the
 *  file still round-trips byte for byte.
 */
export type Setting = "Null" | boolean | number | number | null | string | Setting[] | { [key in string]: Setting };

/**
 *  One setting a kind declares. Settings live in the inspector; ports live on
 *  the block (SPEC §7).
 */
export type SettingDef = {
	name: string,
	label: string,
	kind: SettingKind,
	/**  The options a `Select` offers. */
	options: string[],
	min: number,
	max: number,
	/**
	 *  Why this setting matters, where that is not obvious. Shown as the hint
	 *  under a switch row; this is where a safety or privacy boundary is stated
	 *  in plain words (SPEC §12).
	 */
	hint: string | null,
};

/**  What kind of control the inspector draws for a setting. */
export type SettingKind = "text" | "multiline" | "number" | 
/**  A number with a floor and a ceiling; the inspector draws a slider. */
"range" | "bool" | "select" | 
/**  A list of strings. */
"list" | 
/**  A filesystem path. */
"path";

/**  Which side of a block a port sits on. */
export type Side = "in" | "out";

export type Size = {
	w: number,
	/**  Height is only meaningful for the views that have one: stage and code. */
	h?: number | null,
};

/**
 *  Where a custom block's code lives. Inline code is embedded in the file as a
 *  block scalar so a diff reads as code.
 */
export type Source = {
	mode: SourceMode,
	language: Language,
	code?: string | null,
	/**  Relative to the workspace folder, so a graph moves with its files. */
	path?: string | null,
};

/**
 *  What went wrong, and where.
 * 
 *  A parse failure is shown on the block with its line number while the
 *  previous interface stays, so the graph keeps running around it (§10.4).
 *  That is only possible because this reports rather than throws.
 */
export type SourceError = {
	/**  1-based, so it matches what an editor's gutter says. */
	line: number,
	message: string,
};

/**  Where a custom block's code lives. */
export type SourceMode = "inline" | "file";

export type Ui = {
	viewport: Viewport,
};

export type Value = { type: "text"; value: string } | 
/**
 *  Arbitrary JSON.
 * 
 *  Exported as `unknown` rather than structurally: specta refuses to write
 *  `serde_json::Value` because its `Number` holds an `i64` and TypeScript
 *  cannot hold one without losing precision. `unknown` is the truthful type
 *  anyway — this is a record whose shape the block decides, and the shell
 *  should be made to look before it reads.
 */
{ type: "data"; value: unknown } | 
/**
 *  A path on disk. Held as a string rather than a `PathBuf` because it
 *  crosses the socket as JSON and the shell shows it verbatim.
 */
{ type: "file"; value: string } | { type: "image"; value: Media } | { type: "audio"; value: Media } | 
/**
 *  A port that produced nothing. Distinct from a port that was never
 *  reached: the plan knows the difference and the console says which.
 */
{ type: "null" };

/**
 *  How much of a block is drawn. Every block has compact and summary; a custom
 *  block's third view is its code, a block with a picture is its stage.
 */
export type View = "compact" | "summary" | "code" | "stage";

export type Viewport = {
	x: number,
	y: number,
	zoom: number,
};

/**  One typed connection. Endpoints are written as `block.port`. */
export type Wire = {
	id: string,
	from: Endpoint,
	to: Endpoint,
};
